INSERT INTO projects (id, technology_id, lab_id, name, status, application_summary, business_thesis, target_customer, problem, licensing_status, licensing_pathway, licensing_pathway_notes, risks) VALUES (pid, tid, lid, '[SAMPLE] HarborTrace Instruments', 'proposal_in_preparation', '[SAMPLE] Ammonia-monitoring hardware with replaceable cartridges for industrial wastewater operators.', '[SAMPLE] HarborTrace would help mid-sized industrial wastewater plants detect process changes sooner with less manual sampling. Start with 90-day operational pilots, not compliance reporting. The sensor cartridge was selected over an optical module and corrosion patch because the proposed team knows wastewater operations and can test one measurable problem. Demand, field reliability and licensing rights are still unproven.', '[SAMPLE] Environmental managers at industrial sites with on-site wastewater treatment; operators are users, the plant manager controls pilot spend.', '[SAMPLE] Manual grab samples leave gaps between measurements. Installed analyzers can require frequent cleaning. We need to prove that the proposed sensor reduces total operator effort, not merely that it measures ammonia.', 'researching', 'evaluation_license', '[SAMPLE] Explore a six-month evaluation right before negotiating commercial rights. This is a proposed pathway, not an executed agreement. No assumed exclusivity, fees or royalties.', '[SAMPLE] Matrix interference, fouling, unknown IP access, weak willingness-to-pay evidence, procurement delays and grant dependence. Stop if real-water tests or pilot economics fail.');
