INSERT INTO status_history (project_id, from_status, to_status, reason, created_at) VALUES (pid, 'technology_selected', 'validating_opportunity', '[SAMPLE] Five simulated interviews show mixed interest, with maintenance a recurring objection.', now() + interval '-21 days');
INSERT INTO status_history (project_id, from_status, to_status, reason, created_at) VALUES (pid, 'validating_opportunity', 'investigating_licensing', '[SAMPLE] Recorded unresolved IP questions; evaluation license is preferred, not secured.', now() + interval '-14 days');
