INSERT INTO proposals (id, project_id, opportunity_id, title, status, notes) VALUES (prid, pid, oid, '[SAMPLE] HarborTrace Phase I feasibility proposal', 'drafting', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. Practice draft only. Do not submit these materials. No checklist item is confirmed against an actual solicitation.');
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Technical problem and proposed solution', 'section', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. Operators need timely process measurements without increasing calibration and cleaning workload. HarborTrace proposes a replaceable ammonia-sensing cartridge plus an operator display. Intended use is operational monitoring, not permit-compliance reporting.', true, '[SAMPLE] Document baseline sampling effort at real sites.', 'drafting', 0);
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Innovation and competitive advantage', 'section', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. The proposed advantage is reduced maintenance burden at comparable accuracy. Do not claim better performance than installed probes until side-by-side testing measures accuracy, drift, cleaning time and cost.', true, '[SAMPLE] Competitor specifications and independent head-to-head data.', 'needs_evidence', 1);
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Research objectives and technical milestones', 'section', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. Objective 1, months 1-2: build five cartridges and test a 1-50 mg/L NH4-N range. Target error is <=10% or 0.5 mg/L, whichever is larger. Objective 2, months 3-4: test three wastewater matrices for 30 days, targeting <=10% drift after calibration. Objective 3, months 5-6: prepare a 90-day operational pilot with two sites and a written maintenance protocol. These are proposed gates, not achieved results.', true, '[SAMPLE] Raw paired measurements, reference-method details, maintenance logs and QA protocol.', 'drafting', 2);
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Technical feasibility and preliminary evidence', 'section', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. The fictional bench scenario has 18 synthetic-water measurements across three concentrations. Mean absolute error is assumed at 7%; this small, invented dataset says nothing about real-water fouling or commercial performance. No real experiment has occurred.', true, '[SAMPLE] Actual lab report, raw data, replicates and method validation.', 'needs_evidence', 3);
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Commercial applications and customer demand', 'section', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. Five simulated interviews: three operators describe a meaningful problem, one partly agrees and one sees no need. Two express conditional pilot interest. None commits to buy. This is a small convenience sample, not market validation.', true, '[SAMPLE] Real interviews, purchase-process map and nonbinding pilot-interest letters.', 'needs_evidence', 4);
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Market and competition', 'section', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. A bottom-up exercise assumes 500 reachable sites at $4,800 annual consumables revenue each: $2.4M annual recurring potential, not a sourced market estimate. Existing manual tests and installed probes compete on cost, accuracy and maintenance. Validate the count and buyer budgets before using this estimate.', true, '[SAMPLE] Sourced site counts, buyer budget evidence and competitor costs.', 'drafting', 5);
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Development and commercialization strategy', 'section', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. Complete six-month feasibility work first. Proceed to field pilots only if performance and IP gates pass. Convert to a paid product after reliability and procurement checks. Phase II is competitive, not guaranteed; private pilot revenue and other financing are alternatives.', true, '[SAMPLE] Evaluation rights, pilot agreements and financing options.', 'drafting', 6);
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Project team and relevant expertise', 'section', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. Fictional team: Maya Chen, founder and instrumentation engineer; Luis Rivera, sensor chemist; part-time field-operations adviser still to recruit. Founder eligibility as PI and all employment commitments are unresolved. Names describe fictional personas, not real experts.', true, '[SAMPLE] Actual CVs, employment commitments and PI eligibility review.', 'drafting', 7);
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Budget and justification', 'document', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. Illustrative six-month research budget: personnel $120,000; fringe $30,000; materials $24,000; external analytical testing $18,000; travel $6,000; indirect costs $42,000. Total $240,000. Fringe assumes 25% of personnel; indirect costs assume 21.2121% of the $198,000 direct-cost base. Neither rate is negotiated or approved. No fee or TABA is included. Verify allowable costs and subcontract limits.', true, '[SAMPLE] Supplier quotes, rate basis and actual solicitation budget instructions.', 'drafting', 8);
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Company information, registrations and certifications', 'certification', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. HarborTrace is a fictional pre-revenue U.S. startup with two founders. No real entity, UEI, SAM registration, SBIR registry ID or certifications exist. The demo does not mark any registration as completed.', true, '[SAMPLE] Actual formation, ownership, size, registration and certifications.', 'needs_evidence', 9);
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Research partners and subcontractors', 'section', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. An external analytical laboratory would compare sensor outputs with reference measurements; the proposed $18,000 service is a budget assumption. No partner has agreed to participate. This exercise is SBIR, not STTR.', true, '[SAMPLE] Statement of work, quote and allowed work-allocation check.', 'drafting', 10);
INSERT INTO proposal_sections (proposal_id, title, kind, required_status, guidance, draft, draft_is_ai_generated, evidence_needed, status, sort) VALUES (prid, '[SAMPLE] Letters of support / IP access evidence', 'evidence', 'confirm_in_solicitation', 'This is a practice outline. Confirm required sections, limits and format against a real solicitation.', '[SAMPLE] Fictional training scenario. All company facts, interviews, measurements, prices, schedules and funding examples are invented. No actual application, license, award or customer commitment exists. Request evidence of evaluation rights from the actual IP owner and pilot-interest letters from real sites. No letters exist in this demo, and no lab endorsement should be implied.', true, '[SAMPLE] Authentic lab and pilot letters with permission to use them.', 'needs_evidence', 11);
